params.query:
# radar-backtest cordis_sparql dataset=organisations page
PREFIX eurio: <http://data.europa.eu/s66#>
SELECT (REPLACE(STR(?org), "^.*/", "") AS ?org_id) ?pic ?name ?short_name (STR(?url0) AS ?url) ?country
WHERE {
  ?org a eurio:Organisation .
  OPTIONAL { ?org eurio:identifier ?pic }
  OPTIONAL { ?org eurio:legalName ?name }
  OPTIONAL { ?org eurio:hasAcronym ?acr . ?acr eurio:shortForm ?short_name }
  OPTIONAL { ?org eurio:url ?url0 . FILTER(!REGEX(STR(?url0), "[^\\s@:/]+@[^\\s@/]+\\.[^\\s@/]+")) }
  OPTIONAL { ?org eurio:hasSite ?site . ?site eurio:hasAddress ?adr . ?adr eurio:addressCountry ?country }
}
ORDER BY ?org ?pic ?name ?short_name ?url0 ?country
LIMIT 10000 OFFSET 20000
